import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def count_lucky_days(l_str: str) -> str:
    l, r = map(int, l_str.strip().split())

    def count_legit_primes(ll, rr):
        count = 0
        for n in range(ll, rr + 1):
            if n == 2 or (n % 4 == 1 and is_prime(n)):
                count += 1
        return count

    result = count_legit_primes(l, r)
    return str(result) + '\n'

def solution(input_str: str) -> str:
    return count_lucky_days(input_str)
