        return "0\n"

    k = n + 1 - 2 * m

    if k <= 0:
        return "0\n"

    total = 0
    for i in range(3, n + 1):
        total += nCr(n, i) - nCr(n - k, i)

    total += 0

    result = 0
    for i in range(1, k + 1):
        result += 3 * nCr(k, i)

    if k > 2:
