import sys

sys.setrecursionlimit(10000)

def find_components(grid, n, m):
    visited = [[False] * m for _ in range(n)]
    components = []

    for i in range(n):
        for j in range(m):
            if not visited[i][j] and grid[i][j] == '.':
                comp = []
                q = [(i, j)]
                visited[i][j] = True

                while q:
                    x, y = q.pop()
                    comp.append((x, y))
                    for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if not visited[nx][ny] and grid[nx][ny] == '.':
                                visited[nx][ny] = True
                                q.append((nx, ny))
                components.append(comp)

    return components

def make_rectangle(grid, n, m):
    components = find_components(grid, n, m)

    for comp in components:
        xs = [r for r, c in comp]
        ym = [c for r, c in comp]
        min_x, max_x = min(xs), max(xs)
        min_y, max_y = min(ym), max(ym)

        is_rect = len(comp) == (max_x - min_x + 1) * (max_y - min_y + 1)

        if not is_rect:
            for x in range(min_x, max_x + 1):
                for y in range(min_y, max_y + 1):
                    grid[x][y] = '.'

    return grid

def to_string(grid):
    return '\n'.join(''.join(row) for row in grid)

def solution(input_data):
