def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    pos = set()
    values = set()
    present = set()

    for i in range(n):
        if a[i] == -1:
            pos.add(i)
        else:
            present.add(a[i])

    all_values = set(range(1, n + 1))
    missing = all_values - present

    total_missing = len(missing)
    known_count = n - total_missing

    k1 = 0
    for idx in pos:
        if idx in missing:
            k1 += 1

    k2 = total_missing - k1

    def factorial(x):
        result = 1
        for i in range(2, x + 1):
            result = result * i % MOD
        return result

    inv = [1] * MOD
    inv[1] = MOD - 2
    for i in range(2, MOD):
        inv[i] = inv[MOD % i] * (MOD // i) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        num = factorial(n)
        den = (factorial(r) * factorial(n - r)) % MOD
        return num * pow(den, MOD - 2, MOD) % MOD

    dp = [0] * (total_missing + 1)
    dp[0] = 1
    for i in range(1, total_missing + 1):
        dp[i] = (dp[i - 1] * (n - i + 1)) % MOD

    def deranged(m):
        if m == 0:
            return 1
        return (factorial(m) * sum((-1) ** i * inv[i] for i in range(m + 1))) % MOD

    if k1 == 0:
        return str(dp[total_missing])
    else:
        total_ways = dp[total_missing] * deranged(total_missing) % MOD
        return str(total_ways)
