            return
        visited[u] = 1
        depth[u] = d
        parent[u] = p

        for v in adj[u]:
            if not visited[v]:
                dfs(v, d + 1, u)
            elif v != p:
                nonlocal cycle_vertices, is_cycle_found
                cycle_vertices = []
                curr = u
                while curr != v:
                    cycle_vertices.append(curr)
                    curr = parent[curr]
                cycle_vertices.append(v)
                is_cycle_found = True
                cycle_vertices.reverse()

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, 1, 0)
            if is_cycle_found:
                break

    if is_cycle_found:
        return f"2\n{k}\n' '.join(map(str, cycle_vertices))\n"

    independent_set = []
    for d in range(1, n + 1):
        count = 0
        target = None
        for u in range(1, n + 1):
            if visited[u] and depth[u] == d:
                count += 1
                target = u
        if count >= k:
            for u in range(1, n + 1):
