        k = parts[0]
        literals = parts[1:]
        clauses.append(literals)
        for lit in literals:
            var = abs(lit)
            var_clauses[var].append((i, lit))

    assignment = [None] * (m + 1)
    clause_satisfied = [False] * n
    well = set()

    def propagate():
        nonlocal well
        while well:
            lit = well.pop()
            if assignment.get(lit) is None and abs(lit) <= m:
                continue

            var_abs = abs(lit)
            var = lit

            for c_idx, _ in var_clauses[var_abs]:
                if clause_satisfied[c_idx]:
                    continue
                if assignment.get(var) == var:
                    for l in clauses[c_idx]:
                        if assignment.get(l, None) is None:
                            assignment[l] = l
                            well.add(l)
                    clause_satisfied[c_idx] = True
                elif assignment.get(l) == l and l != var:
                    assignment[var] = var
                    well.add(var)

    for i in range(n):
        for lit in clauses[i]:
            if assignment.get(lit, None) is None:
                assignment[lit] = lit
                propagate()
                break
        else:
            for lit in clauses[i]:
                if assignment.get(lit, None) is None:
                    assignment[lit] = lit
                    propagate()
                break

    result = []
    for i in range(1, m + 1):
        if assignment.get(i, None) is None:
            result.append('0')
        elif assignment.get(i) == i:
            result.append('1')
        else:
            result.append('0')

    return 'YES\n' + ''.join(result) if all(clause_satisfied) else 'NO\n'
