from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.capacity = {}

    def add_edge(self, u, v, cap):
        self.adj[u].append(v)
        self.adj[v].append(u)
        self.capacity[(u, v)] = cap

    def bfs(self, s, t):
        visited = [-1] * self.n
        visited[s] = 0
        queue = deque([s])
        while queue:
            v = queue.popleft()
            for w in self.adj[v]:
                if visited[w] == -1 and self.capacity.get((v, w), 0) > 0:
                    visited[w] = visited[v] + 1
                    queue.append(w)
        return visited[t] != -1

    def dfs(self, u, t, flow, level):
        if u == t:
            return flow
        seen = set()
        for v in self.adj[u]:
            if v not in seen and self.capacity.get((u, v), 0) > 0 and level[u] < level[v]:
                seen.add(v)
                pushed = self.dfs(v, t, min(flow, self.capacity[(u, v)]), level)
                if pushed > 0:
                    self.capacity[(u, v)] -= pushed
                    self.capacity[(v, u)] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            level = [-1] * self.n
            level[s] = 0
            for v in self.adj[s]:
                if self.capacity.get((s, v), 0) > 0:
                    level[v] = 1
            while True:
                pushed = self.dfs(s, t, float('inf'), level)
                if pushed == 0:
                    break
                flow += pushed
        return flow

