        sz = [node]
        dp[node] = {}
        dp[node][1] = 1

        for child in adj[node]:
            if child == parent:
                continue
            child_results = dp(child, node)

            new_dp = {}
            for s in sz:
                if s in dp[node]:
                    new_val = dp[node][s]
                for e in child_results:
                    if e + s <= n:
                        new_val2 = dp[node].get(s + e, dp[node].get(s, 1) * e)

            for s in dp[node]:
                for e, val in child_results.items():
                    new_size = s + e
                    product_val = dp[node][s] * val
                    if new_size not in dp[node]:
                        dp[node][new_size] = 0
                    dp[node][new_size] = max(dp[node][new_size], product_val) * val

            sz.extend([e for e in child_results])

        return dp[node]

    dp(1, -1)
    max_product = 0
    for s, p in dp[1].items():
        if s == n:
            max_product = max(max_product, p)

