def is_gp(arr):
    n = len(arr)
    if n <= 1:
        return True
    if n <= 2:
        return True

    # All elements must be zero if first is zero
    if arr[0] == 0:
        for x in arr:
            if x != 0:
                return False
        return True

    ratio_num = arr[1]
    ratio_den = arr[0]

    # Avoid division by zero
    for i in range(2, n):
        if arr[i] == arr[i-1] * (ratio_num // ratio_den if ratio_den != 0 else 0):
            continue
        else:
            # Cross-multiply check: arr[i] * ratio_den == arr[i-1] * ratio_num
            if arr[i] * ratio_den != arr[i-1] * ratio_num:
                return False

    return True
