def compute_prime_factors(n):
    """Compute prime factorization of n, returning a dictionary of prime->exponent"""
    factors = {}
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = 1
    return factors

def compute_sub_product_primes(sub_mask, masks, primes):
    """Build the product of primes based on mask"""
    result = {}
    for i in range(len(primes)):
        if sub_mask & (1 << i):
            for p in primes[i]:
                result[p] = sum(masks[i][p] for i in range(len(primes)))
    return result

def split_into_submasks(arr):
    """Split array of numbers into groups based on common prime factors"""
    splits = []
    seen = set()
    for item in arr:
        if item not in seen:
            splits.append([item])
            seen.add(item)
    return splits

