    ts, tf, t = map(int, lines[0].split())
    n = int(lines[1])
    visitors = list(map(int, lines[2].split())) if n > 0 else []

    # Simulate the queue for each visitor and find when the receptionist is free
    free_time = ts

    # Process existing visitors to compute when receptionist finishes serving each
    for v in visitors:
        if free_time < v:
            free_time = max(free_time, v)
        else:
            free_time += t
        if free_time > tf:
            free_time = tf + 1
            break

    # If no visitors, Vasya can arrive at ts (best wait time = 0)
    if n == 0:
        return str(ts)

    # Vasya wants to minimize wait time, so he should arrive early enough
    # to be served, but not so late that he waits in queue

    # Check if Vasya can arrive before all existing visitors
    if visitors[0] > ts:
        # He can arrive at ts (wait time = 0)
        return str(ts)

    # Check if he can arrive after service of last visitor is complete
    # Try arriving right after receptionist is free
    if free_time <= tf:
        return str(max(ts, free_time))

    # Fallback: try arriving earlier
    best_arrival = ts

    for i in range(n):
        if visitors[i] > best_arrival:
            best_arrival = visitors[i]

    return str(best_arrival)
