        for j in range(ord(c) + 1, 255):
            ch = chr(j)
            if ch in is_vowel and ch.isalpha():
                prefix.append(ch)
                if check(prefix):
                    result = ''.join(prefix) + 'a' * (n - len(prefix))
                    break
                prefix.pop()
        if result:
            break

    if result and check(result[:n-1]):
        return result

