            # Determine which is parent
            if len(adj[neighbor]) < deg[v]:
                parent = neighbor
                break

        if parent is None:
            continue

        # Check if removing v and connecting to children maintains tree structure
        # Use DFS to verify tree structure
        visited = set()
        def dfs_check(node):
            if node == v:
                return True
            for child in adj[node]:
                if child != v and child != parent:
                    if dfs_check(child):
                        visited.add(child)
            return True

        if not dfs_check(v):
            results.append(v)

    results = sorted(list(set(results)))
    count = len(results)
    return f"{count}\n{' '.join(map(str, results))}" if count > 0 else "0\n"
