        if visited_count == k:
            return 1
        total = 0
        next_pos_limit = min(n, last_pos + m)
        for y in range(1, next_pos_limit + 1):
            if not (visited_mask & (1 << (y - 1))):
                total = (total + count_ways(visited_mask | (1 << (y - 1)), y)) % MOD
        return total

    total = 0
    for start in range(1, n + 1):
        total = (total + count_ways((1 << (start - 1)), start)) % MOD

