    preferences = []
    for i in range(n):
        pref_list = []
        for j in range(n):
            if costs[i][j] < float('inf'):
                pref_list.append((costs[i][j], j))
        pref_list.sort()
        preferences.append([p[1] for p in pref_list])

    # Gale-Shapley algorithm for stable matching
    matched = [-1] * n
    unmatched = list(range(n))
    proposals = [0] * n  # Current proposal index for each city

    while unmatched:
        city = unmatched.pop(0)
        if not proposals[city]:
            return "-1\n"

        candidate = preferences[city][proposals[city]]
        if matched[candidate] == -1:
            matched[city] = candidate
            matched[candidate] = city
        else:
            matched_city = matched[candidate]
            # Compare new preference vs current
            if costs[city][candidate] < costs[city][matched_city]:
                matched[city] = candidate
                matched[candidate] = city
                unmatched.append(matched_city)
            else:
                unmatched.append(city)
        proposals[city] += 1

    result = []
    for i in range(n):
        result.append(str(matched[i] + 1))

    return "\n".join(result) + "\n"
