def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])
    ranges = []
    for i in range(1, n + 1):
        li, ri = map(int, lines[i].split())
        ranges.append((li, ri))

    # Build connectivity graph
    # Two sheep i and j are connected if their ranges intersect
    connected = {}
    for i in range(n):
        connected[i] = []
    for i in range(n):
        li, ri = ranges[i]
        for j in range(i + 1, n):
            lj, rj = ranges[j]
            if max(li, lj) <= min(ri, rj):
                connected[i].append(j)
                connected[j].append(i)

    # Initialize DSU to find connected components
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Union all connected nodes
    for node in connected:
        for neighbor in connected[node]:
            union(node, neighbor)

    # Group by component
    comps = {}
    for i in range(n):
        comps.setdefault(find(i), []).append(i)

    # Sort each component
    for comp in comps.values():
        comp.sort()

    # Concatenate all sorted components
    result = []
    for comp in sorted(comps.values(), key=lambda x: min(x)):
        result.extend(sorted(comps[find(min(comp))]))

    # Convert to 1-based indexing
    result = [x + 1 for x in result]

    return ' '.join(map(str, result)) + '\n'
