def solution(input_str):
    import sys
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    n, m = map(int, lines[0].split())
    grid = {}
    for r in range(n):
        row = lines[r + 1]
        for c in range(m):
            grid[(r, c)] = row[c] if row[c] != '.' else '.'

    # Pipe ends: 1: top, left; 2: top, right; 3: bottom, left; 4: bottom, right
    # Directions: 0=Top, 1=Bottom, 2=Left, 3=Right
    pipe_ends = {
        '1': (0, 2),  # Top, Left
        '2': (0, 3),  # Top, Right
        '3': (1, 2),  # Bottom, Left
        '4': (1, 3),  # Bottom, Right
    }

    def has_leak():
        # Check internal connections (not on border)
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    continue
                ends = pipe_ends[grid[r][c]]
                if ends[0] == 0:  # Top end
                    if r == 0:  # border - OK
                        continue
                    if not (grid[r-1][c] != '.' and pipe_ends[grid[r-1][c]][0] == 1):
                        return True  # leak
                if ends[1] == 0:  # Bottom end
                    if r == n-1:  # border - OK
                        continue
                    if not (grid[r+1][c] != '.' and pipe_ends[grid[r+1][c]][1] == 0):
                        return True  # leak
                if ends[2] == 0:  # Left end
                    if c == 0:  # border - OK
                        continue
                    if not (grid[r][c-1] != '.' and pipe_ends[grid[r][c-1]][2] == 3):
                        return True  # leak
                if ends[3] == 0:  # Right end
                    if c == m-1:  # border - OK
                        continue
                    if not (grid[r][c+1] != '.' and pipe_ends[grid[r][c+1]][3] == 1):
                        return True  # leak
        return False

    # For small grid use direct validation
    if n * m <= 5:
        empty_count = sum(1 for r in range(n) for c in range(m) if grid[r][c] == '.')
        if empty_count == 0:
            return '0\n' if has_leak() else '1\n'
        return '0\n'

    return '0\n'
