        for i in range(n):
            parts = lines[idx].strip().split()
            idx += 1
            if parts[0] == '-1':
                l, r = int(parts[1]), int(parts[2])
                tree[i] = ('internal', l, r)
            else:
                tree[i] = ('value', int(parts[0]))

        # Count leaves in subtree rooted at node
        def count_leaves(node):
            if tree[node][0] == 'value':
                return 1
            return count_leaves(tree[node][1]) + count_leaves(tree[node][2])

        # Compute result for subtree
        def compute(node):
            if tree[node][0] == 'value':
                return tree[node][1]

            left_val = compute(tree[node][1])
            right_val = compute(tree[node][2])

            leaf_count = count_leaves(node)
            moves = leaf_count - 1

            if moves % 2 == 0:
                # Pieguy (maximizer) moves
                return max(left_val, right_val)
            else:
                # Piegirl (minimizer) moves
                return min(left_val, right_val)

        results.append(str(compute(0)))

    return '\n'.join(results)
