import sys
from typing import List, Tuple

def parse_input(data: str) -> Tuple[int, int, int, int, List[Tuple[int, int, int, int]]]:
    lines = data.strip().split('\n')
    n = int(lines[0])
    x1, y1, x2, y2 = map(int, lines[1].split())
    mice = []
    for i in range(n):
        rix, riy, vix, viy = map(int, lines[2 + i].split())
        mice.append((rix, riy, vix, viy))
    return n, x1, y1, x2, y2, mice

def solve(n: int, x1: int, y1: int, x2: int, y2: int, mice: List[Tuple[int, int, int, int]]):
    low_x = 0.0
    high_x = float('inf')
    low_y = 0.0
    high_y = float('inf')

    for rix, riy, vix, viy in mice:
        # Interval for x coordinate
        if vix == 0:
            if not (x1 < rix < x2):
                return "-1"
            # No constraint on t from x
        else:
            left_t = (x1 - rix) / vix
            right_t = (x2 - rix) / vix
            if vix > 0:
                low_x = max(low_x, left_t)
                high_x = min(high_x, right_t)
            else:
                high_x = min(high_x, left_t)
                low_x = max(low_x, right_t)

        # Interval for y coordinate
        if viy == 0:
            if not (y1 < riy < y2):
                return "-1"
            # No constraint on t from y
        else:
            left_t = (y1 - riy) / viy
            right_t = (y2 - riy) / viy
            if viy > 0:
                low_y = max(low_y, left_t)
                high_y = min(high_y, right_t)
            else:
                high_y = min(high_y, left_t)
                low_y = max(low_y, right_t)

    if low_x >= high_x or low_y >= high_y:
        return "-1"

    return str(min(low_x, low_y))

def solution(data: str) -> str:
    n, x1, y1, x2, y2, mice = parse_input(data)
    return solve(n, x1, y1, x2, y2, mice)

