        [(0, 0), (0, 1), (-1, 0), (1, 0)],       # T pointing right
        [(0, 0), (1, 0), (0, 1), (0, -1)],       # T pointing up (another view)
        [(0, 0), (0, -1), (1, 0), (-1, 0)]       # T pointing left
