        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            grid[nr][nc] = '.'
            occupied[nr][nc] = True

    def backtrack(idx, count, char_code):
        if idx == n * m:
            return
        r, c = divmod(idx, m)
        if occupied[r][c]:
