    for aj, zj in mushrooms:
        survival_prob = 1.0
        for ai, hi, li, ri in trees:
            affected_left = (aj >= ai - hi) and (aj < ai)
            affected_right = (aj > ai) and (aj <= ai + hi)

            if affected_left and affected_right:
                prob_not_destroy = 1.0 - li/100.0 - ri/100.0
            elif affected_left:
                prob_not_destroy = 1.0 - li/100.0
            elif affected_right:
                prob_not_destroy = 1.0 - ri/100.0
            else:
                prob_not_destroy = 1.0

            survival_prob *= prob_not_destroy

        total_expected_power += zj * survival_prob

