        col_shift_right = 0
        col_shift_left = 0
        row_shift_down = 0
        row_shift_up = 0

        def apply_inverse_perm(matrix, axis):
            if axis == 'row':
                inv_matrix = []
                for row in matrix:
                    inverse = [0] * n
                    for j, v in enumerate(row):
                        inverse[v - 1] = j + 1
                    inv_matrix.append(inverse)
                return inv_matrix
            else:
