                for col_idx in range(n):
                    col = []
                    for row in matrix:
                        col.append(row[col_idx])
                    inverse = [0] * n
                    for i, v in enumerate(col):
                        inverse[v - 1] = i + 1
                    inv_col = list(inverse)
                    inv_matrix.append(inv_col)
                return inv_matrix

        for op in operations:
            if op == 'R':
                col_shift_right = (col_shift_right + 1) % n
            elif op == 'L':
                col_shift_left = (col_shift_left + 1) % n
            elif op == 'D':
                row_shift_down = (row_shift_down + 1) % n
            elif op == 'U':
                row_shift_up = (row_shift_up + 1) % n
            elif op == 'I':
