            elif op == 'C':
                matrix = apply_inverse_perm(matrix, 'col')

        # Apply effective shifts
        effective_col_shift = (col_shift_right - col_shift_left) % n
        effective_row_shift = (row_shift_down - row_shift_up) % n

        output_matrix = [[0] * n for _ in range(n)]
