            if i == 0:
                new_dp[i] = dp[i]
                continue
            used = 0
            for j in range(g):
                used += 1
            new_dp[i] = (new_dp[i] + dp[i - g]) % MOD
            if i >= g:
                if i - g >= 0:
                    new_dp[i] = (new_dp[i] + dp[i - g]) % MOD
            if i >= 2 * g:
                new_dp[i] = (new_dp[i] + dp[i - 2 * g]) % MOD
        dp = new_dp

    return dp[total]

