def solution(data):
    lines = data.strip().split('\n')
    n, k = map(int, lines[0].split())
    s_list = list(lines[1])

    from collections import deque

    # BFS with (idx, balance)
    visited = set()
    queue = deque([(0, 0)])
    parent = {}

    while queue:
        idx, bal = queue.popleft()
        if idx == n and abs(bal) == k:
            break

        visited.add((idx, bal))
        for c in ['W', 'L', 'D']:
            if idx >= n or s_list[idx] != '?' and s_list[idx] != c:
                continue
            if idx < n and s_list[idx] == '?' or s_list[idx] == c:
                nb = bal + (1 if c == 'W' else -1 if c == 'L' else 0)
                if abs(nb) > k or (idx + 1 < n and abs(nb) == k):
                    continue
                parent[(idx + 1, nb)] = (idx, bal, c)
                queue.append((idx + 1, nb))

    # Reconstruct solution
    if len(visited) < 2:
        return 'NO\n'

    # Rebuild from BFS tree
    ans = []
    curr = (n, 0)
    for i in range(1, n + 1):
        if curr not in parent:
            return 'NO\n'
        _, __, c = parent[curr]
        ans.append(c)
        curr = parent[curr][0:2]

    return ''.join(reversed(ans[:n - 1])) + '\n' if ans else 'NO\n'
