    t = int(lines[0])
    test_cases = [int(lines[i]) for i in range(1, t + 1)]

    # Precompute Fibonacci numbers up to 10^18
    fibs = []
    a, b = 1, 2
    while a <= 10**18:
        fibs.append(a)
        a, b = b, a + b

    def count_decompositions(n):
        memo = {}

        def dp(target, idx):
            if target == 0:
                return 1
            if target < 0 or idx >= len(fibs):
                return 0
            key = (target, idx)
            if key in memo:
                return memo[key]

            with_fib = dp(target - fibs[idx], idx + 1)
            without_fib = dp(target, idx + 1)
            result = with_fib + without_fib
            memo[key] = result
            return result

        return dp(n, 0)

    results = []
    for n in test_cases:
        results.append(str(count_decompositions(n)))

    return '\n'.join(results)
