def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    if k == 0:
        # We need 0 consecutive N, meaning no N positions allowed at all
        if 'N' in s:
            return "NO\n"
        else:
            return "YES\n"

    # Calculate the minimum possible dissatisfaction (all ? set to Y)
    min_max_n = 0
    cur = 0
    for c in s.replace('?', 'Y'):
        if c == 'N':
            cur += 1
            min_max_n = max(min_max_n, cur)
        else:
            cur = 0

    # Calculate the maximum possible dissatisfaction (all ? set to N)
    max_max_n = 0
    cur = 0
    for c in s.replace('?', 'N'):
        if c == 'N':
            cur += 1
            max_max_n = max(max_max_n, cur)
        else:
            cur = 0

    # If we can avoid > k consecutive N's and can achieve >= k consecutive N's,
    # then we can achieve exactly k consecutive N's
    if min_max_n <= k and max_max_n >= k:
        return "YES\n"
    else:
        return "NO\n"
